def _dst(y, mo, d):
    import datetime as _dt
    m1 = _dt.date(y, 3, 1)
    ms = 1 + ((6 - m1.weekday()) % 7) + 7
    n1 = _dt.date(y, 11, 1)
    ne = 1 + ((6 - n1.weekday()) % 7)
    if mo < 3 or mo > 11:
        return False
    if 3 < mo < 11:
        return True
    if mo == 3:
        return d >= ms
    return d < ne


def _et_minutes(bars):
    """Minute-of-day in America/New_York for every bar. UTC in, ET out."""
    off = {}
    out = []
    for b in bars:
        ts = str(b["t"])
        day = ts[:10]
        o = off.get(day)
        if o is None:
            o = -4 if _dst(int(ts[0:4]), int(ts[5:7]), int(ts[8:10])) else -5
            off[day] = o
        out.append((int(ts[11:13]) + o) * 60 + int(ts[14:16]))
    return out


def family_init(ctx):
    bars = ctx.bars
    n = len(bars)
    h = [float(b["h"]) for b in bars]
    l = [float(b["l"]) for b in bars]
    c = [float(b["c"]) for b in bars]
    et = _et_minutes(bars)
    day = [str(b["t"])[:10] for b in bars]
    R0 = int(ctx.p.rth_open)
    R1 = int(ctx.p.rth_close)
    PER = int(ctx.p.per_min)

    sess = []
    pos = {}
    for j in range(n):
        if not (R0 <= et[j] < R1):
            continue
        d = day[j]
        k = pos.get(d)
        if k is None:
            pos[d] = len(sess)
            k = len(sess)
            sess.append({"d": d, "h": h[j], "l": l[j], "c": c[j], "per": {}})
        s = sess[k]
        if h[j] > s["h"]:
            s["h"] = h[j]
        if l[j] < s["l"]:
            s["l"] = l[j]
        s["c"] = c[j]
        q = (et[j] - R0) // PER
        pr = s["per"].get(q)
        if pr is None:
            s["per"][q] = [l[j], h[j]]
        else:
            if l[j] < pr[0]:
                pr[0] = l[j]
            if h[j] > pr[1]:
                pr[1] = h[j]

    sidx = [0] * n
    cur = -1
    for j in range(n):
        k = pos.get(day[j])
        if k is not None:
            cur = k
        sidx[j] = cur
    ctx.sidx = sidx

    # ---- daily ATR from COMPLETED prior sessions only ----
    wd = int(ctx.p.atr_days)
    atrd = {}
    atrk = [None] * len(sess)
    trs = []
    for k in range(len(sess)):
        s = sess[k]
        if k > 0:
            hist = trs[-wd:]
            if len(hist) >= 2:
                atrd[s["d"]] = sum(hist) / float(len(hist))
                atrk[k] = atrd[s["d"]]
            pc = sess[k - 1]["c"]
        else:
            pc = s["c"]
        trs.append(max(s["h"] - s["l"], abs(s["h"] - pc), abs(s["l"] - pc)))
    ctx.atrd = atrd

    # ---- the TPO profile of each completed session, and its poor extremes ----
    mt = int(ctx.p.min_tpo)
    fn = int(ctx.p.flat_n)
    found = {}
    for k in range(len(sess)):
        A = atrk[k]
        if A is None or A <= 0:
            continue
        s = sess[k]
        wrow = float(ctx.p.row_frac) * A
        if wrow <= 0:
            continue
        counts = {}
        for pr in s["per"].values():
            r0 = int(pr[0] // wrow)
            r1 = int(pr[1] // wrow)
            if r1 - r0 > 400:
                continue
            for r in range(r0, r1 + 1):
                counts[r] = counts.get(r, 0) + 1
        if len(counts) < 3:
            continue
        top = max(counts)
        bot = min(counts)
        hi_flat = sum(1 for pr in s["per"].values() if s["h"] - pr[1] <= wrow)
        lo_flat = sum(1 for pr in s["per"].values() if pr[0] - s["l"] <= wrow)
        ev = []
        if counts.get(top, 0) >= mt and counts.get(top - 1, 0) >= mt \
                and hi_flat >= fn:
            ev.append((1, s["h"]))       # a poor HIGH -- buy toward it
        if counts.get(bot, 0) >= mt and counts.get(bot + 1, 0) >= mt \
                and lo_flat >= fn:
            ev.append((-1, s["l"]))      # a poor LOW -- sell toward it
        if ev:
            found[k] = ev
    ctx.found = found
    ctx._reg = []
    ctx._sess = -1
    ctx._t0 = None
    ctx._tgt = None
    ctx._stp = None


def signal(ctx, i):
    s = ctx.sidx[i]
    if s < 1:
        return 0
    if s != ctx._sess:
        # a session closed: register whatever it left unfinished, and age out
        for ev in ctx.found.get(s - 1, ()):
            ctx._reg.append({"dir": ev[0], "px": ev[1], "s": s - 1, "used": -1})
        dep = int(ctx.p.reg_depth)
        ctx._reg = [r for r in ctx._reg if s - r["s"] <= dep]
        ctx._sess = s
    if not ctx._reg:
        return 0
    A = ctx.atrd.get(str(ctx.t[i])[:10])
    if A is None or A <= 0:
        return 0
    rep = float(ctx.p.repair) * A
    app = float(ctx.p.approach) * A
    keep = []
    out = 0
    for r in ctx._reg:
        if r["dir"] > 0:
            if ctx.h[i] > r["px"] + rep:
                continue                 # repaired: the auction finished the job
        else:
            if ctx.l[i] < r["px"] - rep:
                continue
        keep.append(r)
        if out or r["used"] == s or ctx.positions:
            continue
        if r["dir"] > 0:
            if ctx.h[i] >= r["px"] - app and ctx.c[i] < r["px"] \
                    and ctx.c[i] > ctx.o[i]:
                r["used"] = s
                ctx._t0 = s
                ctx._tgt = r["px"] + rep
                ctx._stp = float(ctx.p.stop_f) * A
                out = 1
        else:
            if ctx.l[i] <= r["px"] + app and ctx.c[i] > r["px"] \
                    and ctx.c[i] < ctx.o[i]:
                r["used"] = s
                ctx._t0 = s
                ctx._tgt = r["px"] - rep
                ctx._stp = float(ctx.p.stop_f) * A
                out = -1
    ctx._reg = keep
    return out


def exit_signal(ctx, i):
    if not ctx.positions or ctx._t0 is None:
        return False
    if ctx.sidx[i] - ctx._t0 >= int(ctx.p.hold_sess):
        return True
    p = ctx.positions[0]
    if p["side"] == "long":
        if ctx._tgt is not None and ctx.h[i] >= ctx._tgt:
            return True
        return ctx.c[i] <= p["entry"] - ctx._stp
    if ctx._tgt is not None and ctx.l[i] <= ctx._tgt:
        return True
    return ctx.c[i] >= p["entry"] + ctx._stp
